import sqlite3
from pathlib import Path

schema = Path('schema.sql').read_text(encoding='utf-8')
views = Path('views.sql').read_text(encoding='utf-8')

con = sqlite3.connect(':memory:')
con.executescript(schema)
con.executescript(views)
con.executescript("""
INSERT INTO customers VALUES (1, 'Ada', 'ada@example.com', 'gold');
INSERT INTO customers VALUES (2, 'Bob', 'bob@example.com', 'bronze');
INSERT INTO products VALUES (1, 'Widget', 1000);
INSERT INTO orders VALUES (1, 1, 'paid', '2026-01-01');
INSERT INTO orders VALUES (2, 2, 'paid', '2026-01-01');
INSERT INTO order_items VALUES (1, 1, 1, 10, 1000);
INSERT INTO order_items VALUES (2, 2, 1, 10, 1000);
""")

gold = con.execute(
    'SELECT total_cents, discounted_total_cents FROM customer_order_totals WHERE customer_id = 1'
).fetchone()
bronze = con.execute(
    'SELECT total_cents, discounted_total_cents FROM customer_order_totals WHERE customer_id = 2'
).fetchone()

assert gold[0] == 10000 and bronze[0] == 10000, (gold, bronze)
assert gold[1] == 9000, (
    f'gold tier gets a 10% discount: expected discounted_total_cents 9000, got {gold[1]}')
assert bronze[1] == 10000, (
    f'bronze tier gets no discount: expected discounted_total_cents 10000, got {bronze[1]} - '
    f'discounted_total_cents must not just mirror total_cents, it must actually apply the '
    f"customer's loyalty_tier")

print('PASS')

reference_solution.schema.sql:
CREATE TABLE customers (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    loyalty_tier TEXT NOT NULL DEFAULT 'bronze' CHECK (loyalty_tier IN ('bronze', 'silver', 'gold'))
);

CREATE TABLE products (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    price_cents INTEGER NOT NULL CHECK (price_cents >= 0)
);

CREATE TABLE orders (
    id INTEGER PRIMARY KEY,
    customer_id INTEGER NOT NULL REFERENCES customers(id),
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'paid', 'shipped')),
    created_at TEXT NOT NULL
);

CREATE TABLE order_items (
    id INTEGER PRIMARY KEY,
    order_id INTEGER NOT NULL REFERENCES orders(id),
    product_id INTEGER NOT NULL REFERENCES products(id),
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    unit_price_cents INTEGER NOT NULL
);

